@'
$files = Get-ChildItem -Recurse -File "C:\Users\LGZYcn\.codex\sessions" | Sort-Object LastWriteTime
foreach ($f in $files) {
  $counts = @{}
  $first = $null; $last = $null; $cwd = $null; $n = 0
  Get-Content $f.FullName -Encoding UTF8 | ForEach-Object {
    $n++
    try { $o = $_ | ConvertFrom-Json } catch { return }
    $t = $o.type
    $counts[$t] = 1 + ($counts[$t] -as [int])
    if ($o.type -eq 'session_meta') { $cwd = $o.payload.cwd }
    if ($o.type -eq 'response_item' -and $o.payload.role -eq 'user') {
      $txt = ($o.payload.content | Where-Object { $_.type -eq 'input_text' } | ForEach-Object { $_.text }) -join "`n"
      if ($txt -notmatch '^<environment_context>' ) {
        if (-not $first) { $first = ($txt -replace "`n",' ').Substring(0,[Math]::Min(80,$txt.Length)) }
        $last = ($txt -replace "`n",' ').Substring(0,[Math]::Min(80,$txt.Length))
      }
    }
  }
  Write-Output ("### {0} | lines={1} | cwd={2}" -f $f.Name, $n, $cwd)
  Write-Output ("  types: " + (($counts.GetEnumerator() | Sort-Object Name | ForEach-Object { "$($_.Key)=$($_.Value)" }) -join ', '))
  Write-Output ("  first user: " + $first)
  Write-Output ("  last  user: " + $last)
}
