@'
$outDir = "C:\Users\LGZYcn\Documents\Codex\2026-09-17\jian\work\transcripts"
New-Item -ItemType Directory -Force -Path $outDir | Out-Null
$files = Get-ChildItem -Recurse -File "C:\Users\LGZYcn\.codex\sessions\2026" | Where-Object { $_.Name -notlike '*01a0ae67-4335*' }
foreach ($f in $files) {
  $sb = New-Object System.Text.StringBuilder
  $idx = 0
  Get-Content $f.FullName -Encoding UTF8 | ForEach-Object {
    try { $o = $_ | ConvertFrom-Json } catch { return }
    if ($o.type -ne 'response_item') { return }
    $p = $o.payload
    if ($p.type -ne 'message') { return }
    if ($p.role -ne 'user' -and $p.role -ne 'assistant') { return }
    $txt = ($p.content | Where-Object { $_.type -eq 'input_text' -or $_.type -eq 'output_text' } | ForEach-Object { $_.text }) -join "`n"
    if (-not $txt) { return }
    if ($p.role -eq 'user' -and $txt -match '^\s*<environment_context>') { return }
    if ($p.role -eq 'user' -and $txt -match 'Message Type: (MESSAGE|FINAL_ANSWER)') { return }
    $idx++
    [void]$sb.AppendLine("")
    [void]$sb.AppendLine("===== [$idx] $($p.role.ToUpper()) =====")
    [void]$sb.AppendLine($txt.Trim())
  }
  $name = ($f.BaseName -replace '^rollout-','')
  [System.IO.File]::WriteAllText((Join-Path $outDir "$name.md"), $sb.ToString(), [System.Text.UTF8Encoding]::new($false))
  Write-Output ("{0} -> {1} chars" -f $f.Name, $sb.Length)
}
'@ | Set-Content -Encoding UTF8 "$env:TEMP\extract.ps1"; powershell -NoProfile -ExecutionPolicy Bypass -File "$env:TEMP\extract.ps1"

